348	// classifySemanticCells splits per-cell outcomes into successful pages, hard
349	// failures, and quietly-skipped cells. A cell is skipped — not failed — when
350	// it can't serve the search yet: its gateway has no query-serve route, or the
351	// cluster catalog doesn't expose the placement's jurisdiction at all (a cell
352	// mid-onboarding). Neither is worth warning the user about on every search.
353	func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []string, lastErr error) {
354		var skipped, unmatched []string
355		var unmatchedErr error
356		for _, r := range results {
357			switch {
358			case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
359				skipped = append(skipped, r.group.label())
360			case errors.Is(r.err, search.ErrRepoFilterUnmatched):
361				// The cell answered; the repo filter just matched nothing there.
362				// Quiet like a skip when another cell has results, but if NO cell
363				// matches it must surface as a repo problem, never a region one.
364				unmatched = append(unmatched, r.group.label())
365				unmatchedErr = r.err
366			case r.err != nil:
367				lastErr = r.err
368				failed = append(failed, r.group.label())
369			case r.value != nil:
370				p := semanticCellPage{body: r.value}
371				for _, res := range r.value.Results {
372					// Repo rows never count as an upper tier — they're always
373					// merged regardless of the cell's checkpoint/commit tiers.
374					if res.Type != search.TypeRepo && (tierOf(res) == 0 || tierOf(res) == 1) {
375						p.hasUpper = true
376						break
377					}
378				}
379				pages = append(pages, p)
380			}
381		}
382		if len(skipped) > 0 {
383			logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
384		}
385		if len(unmatched) > 0 {
386			// unmatchedErr carries the server's own message (CellV4 wraps it into
387			// the sentinel) — keep it visible here for diagnosis.
388			logging.Debug(ctx, "semantic search: cells where the repo filter matched nothing", "unmatched_cells", unmatched, "error", unmatchedErr.Error())
389		}
390		if len(pages) == 0 && lastErr == nil {
391			switch {
392			case len(unmatched) > 0:
393				// Takes priority over the region message: a cell answering proves
394				// its region serves semantic search.
395				lastErr = errNoRepoAvailable
396			case len(skipped) > 0:
397				lastErr = errNoRegionAvailable
398			}
399		}
400		return pages, failed, lastErr
401	}
