413	// tier0Row pairs a tier-0 result with its rank within the cell that returned
414	// it — the selection order the mixed-capability fallback preserves (see
415	// sortTier0Rows).
416	type tier0Row struct {
417		r        search.Result
418		cellRank int
419	}
420	
421	// rankSemanticResults buckets every page's rows and applies the SAME ordering
422	// the BFF's cross-cell merge uses (searcher.go / routes/search.ts): repos
423	// first, then tier 0 and tier 1 EACH by rerank score desc (ENT-1425/ENT-1431),
424	// then promoted tier-2 by ANN asc. Ordering by rerank score — not BM25 or the
425	// per-namespace retrieval Score — is what keeps the CLI in parity with the web:
426	// query-serve documents that Score "is not the field results are ordered by …
427	// sorting by it undoes reranking." Tier-2 rows arriving alongside tier 0/1 from
428	// the same cell were deliberately promoted by query-serve; a cell whose page is
429	// entirely tier 2 had nothing better — its ANN fallback, shown (uncapped here)
430	// only when tiers 0/1 are empty everywhere.
431	func rankSemanticResults(pages []semanticCellPage) (merged []search.Result, globalUpper bool) {
432		for _, p := range pages {
433			if p.hasUpper {
434				globalUpper = true
435				break
436			}
437		}
438	
439		var repos, tier1, promotedTier2, fallbackTier2 []search.Result
440		var tier0 []tier0Row
441		for _, p := range pages {
442			cellRank := 0
443			for _, r := range p.body.Results {
444				switch {
445				case r.Type == search.TypeRepo:
446					repos = append(repos, r)
447				case tierOf(r) == 0:
448					tier0 = append(tier0, tier0Row{r: r, cellRank: cellRank})
449					cellRank++
450				case tierOf(r) == 1:
451					tier1 = append(tier1, r)
452				case p.hasUpper:
453					promotedTier2 = append(promotedTier2, r)
454				default:
455					fallbackTier2 = append(fallbackTier2, r)
456				}
457			}
458		}
459		sort.SliceStable(repos, func(i, j int) bool { return repos[i].Meta.Score > repos[j].Meta.Score })
460		merged = append(merged, repos...)
461		if globalUpper {
462			sortTier0Rows(tier0)
463			// Tier 1: rerank score decides, retrieval Score breaks ties. Rows whose
464			// cell fell back (no rerank score) sort last, matching the BFF.
465			sort.SliceStable(tier1, func(i, j int) bool {
466				if ri, rj := rerankOf(tier1[i]), rerankOf(tier1[j]); ri != rj {
467					return ri > rj
468				}
469				return tier1[i].Meta.Score > tier1[j].Meta.Score
470			})
471			sort.SliceStable(promotedTier2, func(i, j int) bool { return annOrScoreOf(promotedTier2[i]) < annOrScoreOf(promotedTier2[j]) })
472			for _, t := range tier0 {
473				merged = append(merged, t.r)
474			}
475			merged = append(merged, tier1...)
476			merged = append(merged, promotedTier2...)
477		} else {
478			sort.SliceStable(fallbackTier2, func(i, j int) bool { return annOrScoreOf(fallbackTier2[i]) < annOrScoreOf(fallbackTier2[j]) })
479			merged = append(merged, fallbackTier2...)
480		}
481		return merged, globalUpper
482	}
