484	// sortTier0Rows orders the tier-0 band the way the BFF's sortTier0 does
485	// (ENT-1431). When EVERY row was judged by the cross-encoder, rerank score
486	// decides and BM25 breaks ties. When any row is missing a rerank score — its
487	// cell predates tier-0 reranking — a global rerank sort would demote all of
488	// that cell's full-phrase hits regardless of relevance, so instead the rows are
489	// interleaved positionally (each cell's #1, then each cell's #2, …), preserving
490	// every cell's own selection order, with BM25 breaking ties between same-rank
491	// rows. Converges to rerank-first once every cell is current.
492	func sortTier0Rows(tier0 []tier0Row) {
493		allScored := true
494		for _, t := range tier0 {
495			if t.r.Meta.RerankScore == nil {
496				allScored = false
497				break
498			}
499		}
500		if allScored {
501			sort.SliceStable(tier0, func(i, j int) bool {
502				if ri, rj := rerankOf(tier0[i].r), rerankOf(tier0[j].r); ri != rj {
503					return ri > rj
504				}
505				return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
506			})
507			return
508		}
509		sort.SliceStable(tier0, func(i, j int) bool {
510			if tier0[i].cellRank != tier0[j].cellRank {
511				return tier0[i].cellRank < tier0[j].cellRank
512			}
513			return bm25Of(tier0[i].r) > bm25Of(tier0[j].r)
514		})
515	}
