517	// dedupSemanticResults removes cross-cell duplicates by type+id (a repo
518	// mirrored across cells returns the same logical result from each), keeping
519	// the first (higher-ranked) copy. Results without an id are always kept. The
520	// per-type dupe tally feeds the total/count corrections.
521	func dedupSemanticResults(merged []search.Result) ([]search.Result, map[string]int) {
522		seen := make(map[string]bool, len(merged))
523		dupesByType := make(map[string]int)
524		deduped := merged[:0]
525		for _, r := range merged {
526			id := r.ResultID()
527			if id == "" {
528				deduped = append(deduped, r)
529				continue
530			}
531			key := r.Type + "\x00" + id
532			if seen[key] {
533				dupesByType[r.Type]++
534				continue
535			}
536			seen[key] = true
537			deduped = append(deduped, r)
538		}
539		return deduped, dupesByType
540	}
