542	// aggregateSemanticTotals sums per-cell totals and counts, minus dedup, and
543	// excluding cells whose entire page was a discarded ANN fallback — their
544	// matches are unreachable, so they must not be advertised.
545	func aggregateSemanticTotals(pages []semanticCellPage, globalUpper bool, dupesByType map[string]int) (int, *search.TypeCounts) {
546		dupes := 0
547		for _, n := range dupesByType {
548			dupes += n
549		}
550		total := -dupes
551		counts := &search.TypeCounts{}
552		for _, p := range pages {
553			if globalUpper && !p.hasUpper {
554				// This page's non-repo rows were its ANN fallback and were
555				// dropped by the merge — those matches are unreachable, so only
556				// its repo rows (which are always merged) may be counted.
557				repoRows := 0
558				if p.body.Counts != nil {
559					repoRows = p.body.Counts.Repos
560				} else {
561					for _, r := range p.body.Results {
562						if r.Type == search.TypeRepo {
563							repoRows++
564						}
565					}
566				}
567				total += repoRows
568				counts.Repos += repoRows
569				continue
570			}
571			total += p.body.Total
572			if p.body.Counts != nil {
573				counts.Repos += p.body.Counts.Repos
574				counts.Checkpoints += p.body.Counts.Checkpoints
575				counts.Commits += p.body.Counts.Commits
576				counts.PRs += p.body.Counts.PRs
577				counts.Sessions += p.body.Counts.Sessions
578			}
579		}

579		}
580		subtractDupeCounts(counts, dupesByType)
581		return max(total, 0), counts
582	}
