584	// mergeSemanticV4Responses interleaves per-cell query-serve responses into one,
585	// applying the SAME ordering query-serve uses within a cell (see
586	// rankSemanticResults); when no cell produced tier 0/1 the ANN-only fallback
587	// tail is shown (deduped, then capped). Results are deduped by type+id and
588	// capped to limit. Rerank scores share a space across cells (same Cohere
589	// model), so interleaving is meaningful.
590	//
591	// Totals/counts include only cells whose results were actually mergeable (see
592	// aggregateSemanticTotals). All-cells-failed is an error; a partial failure is
593	// noted in Warnings and the surviving cells are merged.
594	func mergeSemanticV4Responses(ctx context.Context, limit, page int, results []cellCallResult[*search.Response]) (*search.Response, error) {
595		pages, failed, lastErr := classifySemanticCells(ctx, results)
596		if len(pages) == 0 {
597			if lastErr != nil {
598				return nil, fmt.Errorf("semantic search: %w", lastErr)
599			}
600			return &search.Response{Results: []search.Result{}, Page: 1}, nil
601		}
602		var warnings []string
603		if len(failed) > 0 {
604			// Debug, not Warn: the warning below already reaches the user via
605			// Response.Warnings, and slog's default handler would print a Warn
606			// straight to stderr on commands that never ran logging.Init.
607			logging.Debug(ctx, "semantic search: partial failure; results may be incomplete",
608				"succeeded", len(pages), "total", len(results), "failed_cells", failed)
609			warnings = append(warnings, fmt.Sprintf("search failed in %d of %d regions; results may be incomplete", len(failed), len(pages)+len(failed)))
610		}
611	
612		merged, globalUpper := rankSemanticResults(pages)
613		merged, dupesByType := dedupSemanticResults(merged)
614	
615		// Cap the ANN-only fallback tail AFTER dedup (repos always precede it),
616		// so cross-cell duplicates don't shrink the visible page below the cap.
617		if !globalUpper {
618			nRepos := 0
619			for _, r := range merged {
620				if r.Type != search.TypeRepo {
621					break
622				}
623				nRepos++
624			}
625			if len(merged) > nRepos+mergedTier2Max {
626				merged = merged[:nRepos+mergedTier2Max]
627			}
628		}
629		if limit > 0 && len(merged) > limit {
630			merged = merged[:limit]
631		}
632		if merged == nil {
633			merged = []search.Result{}
634		}
635	
636		total, counts := aggregateSemanticTotals(pages, globalUpper, dupesByType)
637		return &search.Response{
638			Results:  merged,
639			Total:    total,
640			Page:     max(page, 1),
641			Counts:   counts,
642			Warnings: warnings,
643		}, nil
644	}
