139		byJurisdiction := make(map[string]coreapi.Cluster, len(clusters.Clusters))
140		for _, cl := range clusters.Clusters {
141			bySlug[strings.ToLower(strings.TrimSpace(cl.Slug))] = cl
142			// Prefer the default cluster per jurisdiction — matches the auth
143			// layer's resolution when routing by jurisdiction alone. A non-default
144			// cluster is kept only when no default has been seen yet.
145			j := strings.ToLower(strings.TrimSpace(cl.Jurisdiction))
146			if j != "" {
