159				// precise than jurisdiction when a jurisdiction has multiple
160				// cells — mirroring matchClusterByHost in cell_target.go.
161				cl, ok = matchClusterByCellInURL(clusters.Clusters, cells[i].cell)
162			}
163			if !ok && cells[i].jurisdiction != "" {
164				// Last resort: jurisdiction-level fallback using the default
165				// cluster. Less precise, but still routes to the right
166				// jurisdiction when the cell name doesn't appear in any URL.
167				if cl, ok = byJurisdiction[cells[i].jurisdiction]; ok {
