203	// than a jurisdiction-level fallback when multiple clusters share a
204	// jurisdiction — each cluster serves a different cell.
205	func matchClusterByCellInURL(clusters []coreapi.Cluster, cell string) (coreapi.Cluster, bool) {
206		prefix := strings.ToLower(strings.TrimSpace(cell)) + "."
207		for _, cl := range clusters {
