211					continue
212				}
213				u, err := url.Parse(rawURL)
214				if err != nil {
215					continue
216				}
217				if strings.HasPrefix(strings.ToLower(u.Hostname()), prefix) {
218					return cl, true
219				}
220			}
221		}
222		return coreapi.Cluster{}, false

