+				result.Session.Org,
+				result.Session.Repo,
+				result.Session.SessionID,
+				result.Session.CheckpointID,
+			)
+			if index, exists := sessionIndexes[key]; exists {
+				upgradeProjectedSession(&normalized[index], result)
+				continue
+			}
+			sessionIndexes[key] = len(normalized)
+			normalized = append(normalized, result)
