type queryResult struct {
	Q       string      `json:"q"`
	Note    string      `json:"note"`
	Total   int         `json:"total"`
	Results []resultRow `json:"results"`
	Err     string      `json:"err,omitempty"`
}

func rowsFrom(results []searcher.SearchResult) []resultRow {
	rows := make([]resultRow, 0, len(results))
	for _, r := range results {
		repo, title, branch := extract(r)
		rows = append(rows, resultRow{
			Type:    r.Type,
			Repo:    repo,
			Title:   title,
			Tier:    int(r.SearchMeta.Tier),
			Score:   r.SearchMeta.Score,
			Branch:  branch,
			Snippet: r.SearchMeta.Snippet,
		})
	}
	return rows
}

func writeJSON(env, def string, v any) {
	path := os.Getenv(env)
	if path == "" {
		path = def
	}
	enc, _ := json.MarshalIndent(v, "", "  ")
	_ = os.WriteFile(path, enc, 0o644)
	fmt.Fprintf(os.Stderr, "wrote %s\n", path)
}

func main() {
	tpKey := readKey("TP_KEY_FILE", "~/.tp-key")
	cohereKey := readKey("COHERE_KEY_FILE", "~/.cohere-key")
	region := os.Getenv("TP_REGION")
	if region == "" {
		region = "aws-us-east-2"
	}
