// Front door: run the real Search through its public API with the fold flag
// off, then on, per query — no pipeline hooks. Toggling only the public
// SetSessionFoldEnabled means production runs exactly this code.
run := func(q queryEntry, fold bool) (queryResult, error) {
	svc.SetSessionFoldEnabled(fold)
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	resp, err := svc.Search(ctx, "eval-account", searcher.SearchParams{
		Q:       q.Q,
		Types:   []string{"checkpoints", "commits", "sessions"},
		Mode:    searcher.ModeHybrid,
		Page:    1,
		Limit:   limit,
		PerType: searcher.PerTypeLimits{Checkpoints: limit},
	})
	if err != nil {
		return queryResult{Q: q.Q, Note: q.Note, Err: err.Error()}, err
	}
	rows := rowsFrom(resp.Results)
	return queryResult{Q: q.Q, Note: q.Note, Total: len(rows), Results: rows}, nil
}

var off, on []queryResult
for _, q := range queries {
	// Both passes back-to-back on the same query to minimize index drift.
	offR, errOff := run(q, false)
	onR, errOn := run(q, true)
	off = append(off, offR)
	on = append(on, onR)
	if errOff != nil || errOn != nil {
		fmt.Fprintf(os.Stderr, "  %q ERR off=%v on=%v\n", q.Q, errOff, errOn)
		continue
	}
	fmt.Fprintf(os.Stderr, "  %q -> off=%d on=%d\n", q.Q, offR.Total, onR.Total)
}

