// top. The exact/prefix filter bypasses embed/BM25/rerank (which score a hash
// as fuzzy text and prune it); pinning alongside the ranked results means a
// query mixing a SHA with prose gets both the commit and the related work.
var pinnedCommits []SearchResult
if pinnedCh != nil {
	res := <-pinnedCh
	pinnedCommits = res.commits
	finalResults = pinCommits(finalResults, pinnedCommits)
	if res.degraded {
