// Server-side fold (ENT-1595): on the general (no filter_type) path, surface
// checkpoint hits as their owning sessions so the CLI and web render the same
// set. Runs AFTER ranking (and after the commit pin above, which it leaves
// untouched — commit rows pass through the fold) so the rerank candidate pool
// — and thus the commit/PR judged set — is unchanged vs the fold-off path.
// filter_type callers keep raw checkpoint rows (contract preserved).
if s.sessionFoldEnabled && params.FilterType == "" && wantsSessions {
	finalResults, _ = foldCheckpointsIntoSessions(finalResults)
	// Apply author/date filtering to the folded session rows so a session
	// carried only by a filtered-out checkpoint's sibling can't leak past an
