		"v4-ulid-1": {bm25Rows: []map[string]interface{}{weak}, annRows: []map[string]interface{}{}},
		"v4-ulid-2": {bm25Rows: []map[string]interface{}{strong}, annRows: []map[string]interface{}{}},
	})
	t.Cleanup(srv.Close)

	tpuf := NewTurbopufferClient("test-key", nil, noopLogger())
	tpuf.SetBaseURL(srv.URL)

	// Order-preserving reranker: every candidate scores identically, so the
	// carrier binding — not Cohere — decides what the assertions observe.
	reranker := newTestReranker(t, func(w http.ResponseWriter, r *http.Request) {
		var req struct {
			Documents []string `json:"documents"`
		}
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			t.Errorf("decoding rerank request: %v", err)
			return
		}
		pairs := make([][2]float64, len(req.Documents))
		for i := range req.Documents {
			pairs[i] = [2]float64{float64(i), 0.99}
		}
		rerankReply(t, pairs...)(w, r)
	})

	svc := NewService(nil, tpuf, staticEmbedder{}, reranker, noopLogger())
	svc.SetRepoResolver(fakeV4RepoResolver{repos: []V4Repo{
		{FullName: "entirehq/one", ULID: "ulid-1"},
		{FullName: "entirehq/two", ULID: "ulid-2"},
	}})

	resp, err := svc.Search(context.Background(), "acct-1", SearchParams{
		Q: "alpha", Types: []string{"sessions"}, Mode: ModeHybrid,
		Page: 1, Limit: 100, PerType: PerTypeLimits{Checkpoints: 100},
	})
	if err != nil {
		t.Fatalf("Search: %v", err)
	}

	var sessions []SearchResult
	for _, r := range resp.Results {
		if r.Type == "session" {
			sessions = append(sessions, r)
		}
	}
	if len(sessions) != 1 {
		t.Fatalf("expected exactly 1 projected session, got %d", len(sessions))
	}

	got := sessions[0]
	if got.SearchMeta.Snippet != "strong carrier chunk" {
		t.Errorf("session bound to wrong carrier: snippet = %q, want %q",
			got.SearchMeta.Snippet, "strong carrier chunk")
	}
	if got.SearchMeta.BM25Score == nil || *got.SearchMeta.BM25Score != 50 {
		t.Errorf("session inherited wrong carrier score: bm25 = %v, want 50", got.SearchMeta.BM25Score)
	}
	data, ok := got.Data.(SessionResult)
	if !ok {
		t.Fatalf("expected SessionResult, got %T", got.Data)
	}
	if data.SessionID != "s1" {
		t.Errorf("SessionID = %q, want %q", data.SessionID, "s1")
	}
}

// TestSessionCarriesMatchedCheckpointID pins ENT-1604: a projected session
// result must name its carrier checkpoint so the frontend can deep-link to
// that checkpoint's timeline entry instead of the session root. With multiple
// carriers, the ID follows the same best-carrier binding the score and
// snippet use.
func TestSessionCarriesMatchedCheckpointID(t *testing.T) {
	sessionsDisplay := `[{"id":"s1","displayName":"investigate heap growth","prompt":"why does heap grow"}]`

	weak := checkpointRow("cp-weak", "cp-weak", "alpha service", 1, 5)
	weak["sessions_display"] = sessionsDisplay
	strong := checkpointRow("cp-strong", "cp-strong", "alpha service", 1, 50)
	strong["sessions_display"] = sessionsDisplay

	svc := tierService(t, nsBehavior{
		bm25Rows: []map[string]interface{}{weak, strong},
		annRows:  []map[string]interface{}{},
	})

	resp, err := svc.Search(context.Background(), "acct-1", SearchParams{
		Q: "alpha", Types: []string{"sessions"}, Mode: ModeHybrid,
		Page: 1, Limit: 100, PerType: PerTypeLimits{Checkpoints: 100},
	})
	if err != nil {
		t.Fatalf("Search: %v", err)
	}

	sessions := sessionResults(resp)
	if len(sessions) != 1 {
		t.Fatalf("expected exactly 1 projected session, got %d", len(sessions))
	}
	data, ok := sessions[0].Data.(SessionResult)
	if !ok {
		t.Fatalf("expected SessionResult, got %T", sessions[0].Data)
	}
	if data.MatchedCheckpointID != "cp-strong" {
		t.Errorf("MatchedCheckpointID = %q, want %q", data.MatchedCheckpointID, "cp-strong")
	}
}

// TestMatchedCheckpointIDSetOnMultiSessionCheckpoint pins the gate asymmetry:
// a multi-session carrier suppresses the snippet (the chunk belongs to exactly
// one unknown sibling — chunk rows carry no session id) but the checkpoint
// anchor is a membership fact, valid for every session the checkpoint lists,
// so it is set unconditionally.
func TestMatchedCheckpointIDSetOnMultiSessionCheckpoint(t *testing.T) {
	row := checkpointRow("cp-multi", "cp-multi", "alpha service", 1, 50)
	row["sessions_display"] = `[{"id":"s1","prompt":"first"},{"id":"s2","prompt":"second"}]`

	svc := tierService(t, nsBehavior{
		bm25Rows: []map[string]interface{}{row},
		annRows:  []map[string]interface{}{},
	})

	resp, err := svc.Search(context.Background(), "acct-1", SearchParams{
		Q: "alpha", Types: []string{"sessions"}, Mode: ModeHybrid,
		Page: 1, Limit: 100, PerType: PerTypeLimits{Checkpoints: 100},
	})
	if err != nil {
		t.Fatalf("Search: %v", err)
	}

	sessions := sessionResults(resp)
	if len(sessions) != 2 {
		t.Fatalf("expected 2 projected sessions, got %d", len(sessions))
	}
	for _, s := range sessions {
		data, ok := s.Data.(SessionResult)
		if !ok {
			t.Fatalf("expected SessionResult, got %T", s.Data)
		}
		if data.MatchedCheckpointID != "cp-multi" {
			t.Errorf("session %s: MatchedCheckpointID = %q, want %q",
				data.SessionID, data.MatchedCheckpointID, "cp-multi")
		}
		if s.SearchMeta.Snippet != "" {
			t.Errorf("session %s: snippet = %q, want empty on a multi-session carrier",
				data.SessionID, s.SearchMeta.Snippet)
		}
	}
}

func sessionResults(resp *SearchResponse) []SearchResult {
	var sessions []SearchResult
	for _, r := range resp.Results {
		if r.Type == "session" {
			sessions = append(sessions, r)
		}

			// The folded session inherits the checkpoint's final-rank position
			// and SearchMeta (RerankScore/tier/matchType/snippet) — NOT a
			// recomputed Score, which is not the post-rerank ordering signal.
			folded = append(folded, SearchResult{
				Type:       "session",
				Data:       session,
				SearchMeta: r.SearchMeta,
			})

		default:
			folded = append(folded, r) // repo, commit, pr
		}
	}

	return folded, tallyByType(folded)
}

func realSessionKey(sessionID string) string { return "s\x00" + sessionID }

func syntheticSessionKey(org, repo, cpID string) string {
	return "cp\x00" + org + "\x00" + repo + "\x00" + cpID
}

// sessionFromCheckpoint projects a checkpoint result into a session row and
// returns its dedup key. A real session id (the checkpoint's first session)
// keys globally so it merges with a literal session row of the same id and with
// the same session folded from a sibling checkpoint. A checkpoint with no
// session id — multi-session attribution is unknown, and legacy docs predate
// the attribute — folds into its FIRST session only when present; absent, it
// gets a per-checkpoint, REPO-QUALIFIED synthetic identity so two repos' legacy
// checkpoints (checkpoint ids are unique only within a repo) never collapse.
// The durable fix for multi-session attribution is a session_id per chunk row
// in the index (out of scope here).
func sessionFromCheckpoint(cp CheckpointResult) (string, SessionResult) {
	// Prefer the descriptive commit subject over the raw first prompt for the
	// fallback name — the prompt is often a generic mid-session message
	// ("push", "sounds good") that reads as irrelevant, while the commit
	// subject describes the work. This is only a FALLBACK: when session-name
	// hydration is on, the live AI-generated session name overrides it.
	displayName := ""
	if cp.CommitSubject != nil {
		displayName = strings.TrimSpace(*cp.CommitSubject)
	}
	if displayName == "" {
		displayName = strings.TrimSpace(cp.Prompt)
	}
	if displayName == "" {
		displayName = "Untitled session"
	}

	prompt := cp.Prompt
	session := SessionResult{
		DisplayName:    displayName,
		Prompt:         &prompt,
		Org:            cp.Org,
		Repo:           cp.Repo,
		Branch:         &cp.Branch,
		AuthorUsername: cp.AuthorUsername,
		CreatedAt:      cp.CreatedAt,
		CheckpointID:   cp.ID,
		CommitSha:      cp.CommitSha,
		repoID:         cp.repoID, // so hydrateSessionDisplayNames can resolve the live name
	}

	if cp.SessionID != nil && *cp.SessionID != "" {
		session.SessionID = *cp.SessionID
		return realSessionKey(*cp.SessionID), session
	}
	// Legacy/sparse: no session id. The row's identity is its checkpoint
	// (CheckpointID above); SessionID stays empty. NOTE (phase 2): the cross-cell
	// dedupers in the BFF and CLI must key on sessionId FALLING BACK to
	// checkpointId before this flag is enabled in prod — an empty sessionId
	// alone collapses every legacy row into one under the current dedupers.
	return syntheticSessionKey(cp.Org, cp.Repo, cp.ID), session
}

// upgradeSessionFromLiteral overlays a literal session's richer, session-level
// fields onto a row that was folded from a checkpoint (leaner). It keeps the
// row's ranking position/SearchMeta and its checkpoint anchor; it never demotes
// a present value to an empty one.
func upgradeSessionFromLiteral(dst *SearchResult, lit SessionResult) {
	sess, ok := dst.Data.(SessionResult)
	if !ok {
		return
	}
	// Deliberately DO NOT adopt the literal's DisplayName: the projected
	// session's name is the raw first prompt (often a generic mid-session
	// message like "okay we're back to a good spot"), which is worse than the
	// descriptive commit subject the fold already set. The authoritative
	// session name comes from hydrateSessionDisplayNames (the live AI/custom
	// name) downstream; until then the commit subject is the better fallback.
	if lit.Prompt != nil {
		sess.Prompt = lit.Prompt
	}
	if lit.Agent != nil {
		sess.Agent = lit.Agent
	}
	if lit.Model != nil {
		sess.Model = lit.Model
	}
	if lit.StepCount != 0 {
		sess.StepCount = lit.StepCount
	}
	if lit.repoID != "" {
		sess.repoID = lit.repoID
	}
	if lit.AuthorUsername != nil && sess.AuthorUsername == nil {
		sess.AuthorUsername = lit.AuthorUsername
	}
	if lit.Branch != nil && sess.Branch == nil {
		sess.Branch = lit.Branch
	}
	dst.Data = sess
}

// enrichSessionAnchors backfills checkpoint provenance onto an already-emitted
// session row that lacks it (a literal projected survivor has no checkpoint
// anchor). It adopts the anchor ONLY when the checkpoint shares the row's repo
// — a crosslinked session spans repos, and pointing a repo-a row at a repo-b
// checkpoint would mislink navigation. It never overwrites present fields.
func enrichSessionAnchors(dst *SearchResult, from SessionResult) {
	sess, ok := dst.Data.(SessionResult)
	if !ok {
		return
	}
	if sess.Org != from.Org || sess.Repo != from.Repo {
		return // different repo: don't cross-link the anchor
	}
	if sess.CheckpointID == "" {
		sess.CheckpointID = from.CheckpointID
	}
	if sess.CommitSha == nil {
		sess.CommitSha = from.CommitSha
	}
	if sess.repoID == "" {
		sess.repoID = from.repoID
	}
	dst.Data = sess
}

